from pathlib import Path

reader = Path('lib/src/features/reader/reader_audio_sheet.dart')
text = reader.read_text()

anchor = "  @override\n  Widget build(BuildContext context) {\n    final copy = _AudioCopy(Localizations.localeOf(context).languageCode);"
if anchor not in text:
    raise SystemExit('reader build anchor not found')
method = '''  Future<void> _showNarratorPicker(_AudioCopy copy) async {\n    if (widget.availableSources.length <= 1) return;\n    final currentId = widget.controller.config?.id;\n    final selected = await showModalBottomSheet<String>(\n      context: context,\n      isScrollControlled: true,\n      showDragHandle: true,\n      builder: (sheetContext) {\n        final scheme = Theme.of(sheetContext).colorScheme;\n        return SafeArea(\n          top: false,\n          child: FractionallySizedBox(\n            heightFactor: .72,\n            child: Column(\n              children: [\n                Padding(\n                  padding: const EdgeInsets.fromLTRB(20, 4, 20, 14),\n                  child: Row(\n                    children: [\n                      Expanded(\n                        child: Text(\n                          copy.chooseNarrator,\n                          style: Theme.of(sheetContext).textTheme.titleLarge?.copyWith(\n                            fontWeight: FontWeight.w900,\n                          ),\n                        ),\n                      ),\n                      IconButton(\n                        onPressed: () => Navigator.pop(sheetContext),\n                        icon: const Icon(Icons.close_rounded),\n                      ),\n                    ],\n                  ),\n                ),\n                Expanded(\n                  child: ListView.separated(\n                    padding: const EdgeInsets.fromLTRB(14, 0, 14, 24),\n                    itemCount: widget.availableSources.length,\n                    separatorBuilder: (_, __) => const SizedBox(height: 6),\n                    itemBuilder: (context, index) {\n                      final source = widget.availableSources[index];\n                      final selectedSource = source.id == currentId;\n                      final title = source.style == null\n                          ? source.title\n                          : '${source.title} · ${source.style}';\n                      return ListTile(\n                        selected: selectedSource,\n                        selectedTileColor: scheme.primaryContainer.withValues(alpha: .42),\n                        shape: RoundedRectangleBorder(\n                          borderRadius: BorderRadius.circular(18),\n                        ),\n                        leading: CircleAvatar(\n                          backgroundColor: selectedSource\n                              ? scheme.primary\n                              : scheme.surfaceContainerHighest,\n                          foregroundColor: selectedSource\n                              ? scheme.onPrimary\n                              : scheme.onSurfaceVariant,\n                          child: const Icon(Icons.record_voice_over_rounded),\n                        ),\n                        title: Text(\n                          title,\n                          style: const TextStyle(fontWeight: FontWeight.w900),\n                        ),\n                        subtitle: Text(source.attribution),\n                        trailing: selectedSource\n                            ? Icon(Icons.check_circle_rounded, color: scheme.primary)\n                            : null,\n                        onTap: () => Navigator.pop(sheetContext, source.id),\n                      );\n                    },\n                  ),\n                ),\n              ],\n            ),\n          ),\n        );\n      },\n    );\n    if (!mounted || selected == null || selected == currentId) return;\n    await widget.onSourceSelected(selected);\n  }\n\n'''
text = text.replace(anchor, method + anchor, 1)

start_marker = "                          if (widget.availableSources.length <= 1)"
end_marker = "                        ],\n                      ),\n                    ),\n                    IconButton("
start = text.find(start_marker)
if start < 0:
    raise SystemExit('old narrator UI start not found')
end = text.find(end_marker, start)
if end < 0:
    raise SystemExit('old narrator UI end not found')
replacement = '''                          Text(\n                            '${controller.config?.code ?? ''} · ${controller.config?.title ?? ''}',\n                            maxLines: 2,\n                            overflow: TextOverflow.ellipsis,\n                            style: TextStyle(\n                              color: scheme.onSurfaceVariant,\n                              fontWeight: FontWeight.w700,\n                            ),\n                          ),\n                          if (widget.availableSources.length > 1) ...[\n                            const SizedBox(height: 10),\n                            Align(\n                              alignment: AlignmentDirectional.centerStart,\n                              child: OutlinedButton.icon(\n                                onPressed: () => _showNarratorPicker(copy),\n                                icon: const Icon(Icons.record_voice_over_rounded),\n                                label: Text(copy.switchNarrator),\n                              ),\n                            ),\n                          ],\n'''
text = text[:start] + replacement + text[end:]

wrap_start = "                Wrap(\n                  spacing: 8,"
wrap_end = "                if (controller.error != null) ...["
start = text.find(wrap_start)
if start < 0:
    raise SystemExit('old playback controls start not found')
end = text.find(wrap_end, start)
if end < 0:
    raise SystemExit('old playback controls end not found')
new_controls = '''                Row(\n                  children: [\n                    PopupMenuButton<double>(\n                      tooltip: copy.playbackSpeed,\n                      initialValue: controller.rate,\n                      onSelected: controller.setRate,\n                      itemBuilder: (_) => const [\n                        PopupMenuItem(value: .5, child: Text('0.5x')),\n                        PopupMenuItem(value: .75, child: Text('0.75x')),\n                        PopupMenuItem(value: 1.0, child: Text('1x')),\n                        PopupMenuItem(value: 1.25, child: Text('1.25x')),\n                        PopupMenuItem(value: 1.5, child: Text('1.5x')),\n                        PopupMenuItem(value: 2.0, child: Text('2x')),\n                      ],\n                      child: Padding(\n                        padding: const EdgeInsets.symmetric(\n                          horizontal: 12,\n                          vertical: 10,\n                        ),\n                        child: Text(\n                          '${controller.rate.toStringAsFixed(controller.rate % 1 == 0 ? 0 : 2)}x',\n                          style: const TextStyle(\n                            fontSize: 18,\n                            fontWeight: FontWeight.w900,\n                          ),\n                        ),\n                      ),\n                    ),\n                    const Spacer(),\n                    PopupMenuButton<AudioAfterSurahBehavior>(\n                      tooltip: copy.playbackBehavior,\n                      initialValue: AppSettingsScope.of(context).audioAfterSurahBehavior,\n                      onSelected: (value) async {\n                        final settings = AppSettingsScope.of(context);\n                        await settings.setAudioAfterSurahBehavior(value);\n                        controller.setContinueAfterSurah(\n                          value == AudioAfterSurahBehavior.continueNext,\n                        );\n                      },\n                      itemBuilder: (_) => [\n                        PopupMenuItem(\n                          value: AudioAfterSurahBehavior.continueNext,\n                          child: Text(copy.continueNextSurah),\n                        ),\n                        PopupMenuItem(\n                          value: AudioAfterSurahBehavior.stop,\n                          child: Text(copy.stopAtSurahEnd),\n                        ),\n                      ],\n                      icon: const Icon(Icons.queue_music_rounded, size: 29),\n                    ),\n                    const SizedBox(width: 6),\n                    PopupMenuButton<String>(\n                      tooltip: copy.timer,\n                      onSelected: (value) {\n                        if (value == 'end') {\n                          controller.setSleepAtSurahEnd();\n                        } else if (value == 'off') {\n                          controller.setSleepTimer(null);\n                        } else {\n                          controller.setSleepTimer(\n                            Duration(minutes: int.parse(value)),\n                          );\n                        }\n                      },\n                      itemBuilder: (_) => [\n                        for (final minutes in const [10, 20, 30, 45])\n                          PopupMenuItem(\n                            value: '$minutes',\n                            child: Text('$minutes ${copy.minutes}'),\n                          ),\n                        PopupMenuItem(\n                          value: 'end',\n                          child: Text(copy.endOfSurah),\n                        ),\n                        PopupMenuItem(value: 'off', child: Text(copy.off)),\n                      ],\n                      child: SizedBox(\n                        width: 48,\n                        height: 48,\n                        child: Icon(\n                          Icons.schedule_rounded,\n                          size: 31,\n                          color: controller.sleepAtSurahEnd || controller.sleepMinutes != null\n                              ? scheme.primary\n                              : null,\n                        ),\n                      ),\n                    ),\n                  ],\n                ),\n                if (controller.sleepAtSurahEnd || controller.sleepMinutes != null) ...[\n                  const SizedBox(height: 2),\n                  Align(\n                    alignment: AlignmentDirectional.centerEnd,\n                    child: Padding(\n                      padding: const EdgeInsetsDirectional.only(end: 4),\n                      child: Text(\n                        controller.sleepAtSurahEnd\n                            ? copy.endOfSurah\n                            : '${controller.sleepMinutes} ${copy.minutes}',\n                        style: TextStyle(\n                          color: scheme.primary,\n                          fontSize: 11,\n                          fontWeight: FontWeight.w800,\n                        ),\n                      ),\n                    ),\n                  ),\n                ],\n                const SizedBox(height: 4),\n                TextButton.icon(\n                  onPressed: () {\n                    setState(() => _quickControlsVisible = !_quickControlsVisible);\n                    widget.onQuickControlsVisibilityChanged(_quickControlsVisible);\n                  },\n                  icon: Icon(\n                    _quickControlsVisible\n                        ? Icons.visibility_off_outlined\n                        : Icons.visibility_outlined,\n                  ),\n                  label: Text(\n                    _quickControlsVisible ? copy.hideButtons : copy.showButtons,\n                  ),\n                ),\n'''
text = text[:start] + new_controls + text[end:]

copy_anchor = "  String get timer =>\n      _pick('Zamanlayıcı', 'Timer', 'المؤقت', 'Taymer', 'Таймер');"
if copy_anchor not in text:
    raise SystemExit('copy timer anchor not found')
copy_insert = """  String get switchNarrator => _pick(\n    'Okuyucuyu değiştir',\n    'Switch narrator',\n    'تغيير القارئ',\n    'Oxucunu dəyiş',\n    'Сменить чтеца',\n  );\n  String get chooseNarrator => _pick(\n    'Okuyucu seç',\n    'Choose narrator',\n    'اختر القارئ',\n    'Oxucu seç',\n    'Выбрать чтеца',\n  );\n  String get playbackSpeed => _pick(\n    'Oynatma hızı',\n    'Playback speed',\n    'سرعة التشغيل',\n    'Oxutma sürəti',\n    'Скорость воспроизведения',\n  );\n  String get playbackBehavior => _pick(\n    'Sure sonu davranışı',\n    'End-of-surah behavior',\n    'سلوك نهاية السورة',\n    'Surə sonu davranışı',\n    'Поведение в конце суры',\n  );\n"""
text = text.replace(copy_anchor, copy_insert + copy_anchor, 1)
reader.write_text(text)

profile = Path('lib/src/features/profile/profile_screen.dart')
p = profile.read_text()
old = """            onTap: () => Navigator.of(context).push(\n              MaterialPageRoute<void>(builder: (_) => const DownloadsScreen()),\n            ),"""
new = """            onTap: () {\n              HapticFeedback.selectionClick();\n              Navigator.of(context).push(\n                MaterialPageRoute<void>(builder: (_) => const DownloadsScreen()),\n              );\n            },"""
if old not in p:
    raise SystemExit('downloads navigation anchor not found')
p = p.replace(old, new, 1)
profile.write_text(p)

print('Audio v2 polish patch applied')
